inline constexpr unsigned MDI_TABLE_N = sizeof(MDI_TABLE) / sizeof(MDI_TABLE[0]);

// Accepts either "mdi:thermometer" or plain "thermometer". Returns
// nullptr when the name is unknown, so a caller can fall through to its
// device_class mapping rather than drawing a wrong glyph confidently.
inline const char *mdiGlyph(const char *name) {
    if (!name || !name[0]) return nullptr;
    if (name[0] == 'm' && name[1] == 'd' && name[2] == 'i' && name[3] == ':') name += 4;
    for (unsigned i = 0; i < MDI_TABLE_N; i++) {
        const char *a = MDI_TABLE[i].name, *b = name;
        while (*a && *a == *b) { a++; b++; }
        if (!*a && !*b) return MDI_TABLE[i].glyph;
    }
    return nullptr;
}

